113	func runDetect(t *testing.T, reg config.RegistryItem) RegistryGroupDetectedMsg {
114		t.Helper()
115		msg, ok := run(t, detectRegistryGroupCmd(reg, "")).(RegistryGroupDetectedMsg)
116		if !ok {
117			t.Fatal("the Cmd did not return a RegistryGroupDetectedMsg")
118		}
119		return msg
120	}
