124	// CA1 and D23: a refused listing is recorded, and what was last known stays.
125	func TestARefusedListingIsRecordedAndKeepsTheMembersLastKnown(t *testing.T) {
126		for _, code := range []int{http.StatusUnauthorized, http.StatusForbidden} {
127			t.Run(fmt.Sprint(code), func(t *testing.T) {
128				isolateGroupHome(t)
129				known := knownMembers()
130				seedGroup(t, &known, nil)
131				reg := nexusGroupServer(t, replyStatus(code))
132	
133				msg := runDetect(t, reg)
134	
135				if !errors.Is(msg.Err, registrymgr.ErrMembersRefused) {
136					t.Fatalf("msg.Err = %v, want a members refusal", msg.Err)
137				}
138				var refused *registrymgr.MembersRefusedError
139				if !errors.As(msg.Err, &refused) || refused.Status != code {
140					t.Fatalf("msg.Err = %v, want *MembersRefusedError with status %d", msg.Err, code)
141				}
142				if msg.At.IsZero() {
143					t.Error("msg.At is zero: the handler cannot hold the instant the disk holds")
144				}
145	
146				c := openGroupCache(t)
147				entry := c.Get(groupSlug)
148				if entry == nil || len(entry.Members) != 2 {
149					t.Fatalf("listing on disk = %+v, want the 2 members last known (D23)", entry)
150				}
151				if !entry.DiscoveredAt.Equal(known.DiscoveredAt) {
152					t.Errorf("DiscoveredAt = %v, want %v untouched: a refusal is not a listing",
153						entry.DiscoveredAt, known.DiscoveredAt)
154				}
155				r := c.Refusal(groupSlug)
156				if r == nil {
157					t.Fatal("the refusal was not written to the cache")
158				}
159				if r.Status != code || !r.Anonymous {
160					t.Errorf("refusal on disk = %+v, want status %d, anonymous", *r, code)
161				}
162				if !r.At.Equal(msg.At) {
163					t.Errorf("refusal At = %v, msg.At = %v: disk and memory must hold the same instant", r.At, msg.At)
164				}
165			})
166		}
167	}
