169	// A group never listed and then refused has a refusal and still no listing:
170	// "an entry is present" keeps meaning "a settled answer".
171	func TestARefusedGroupNeverListedGetsNoListing(t *testing.T) {
172		isolateGroupHome(t)
173		reg := nexusGroupServer(t, replyStatus(http.StatusForbidden))
174	
175		msg := runDetect(t, reg)
176	
177		if !errors.Is(msg.Err, registrymgr.ErrMembersRefused) {
178			t.Fatalf("msg.Err = %v, want a members refusal", msg.Err)
179		}
180		c := openGroupCache(t)
181		if entry := c.Get(groupSlug); entry != nil {
182			t.Errorf("listing on disk = %+v, want none: a refusal must not read as \"0 members\"", entry)
183		}
184		if c.Refusal(groupSlug) == nil {
185			t.Error("the refusal was not written to the cache")
186		}
187	}
