422	// CA3 on the model side: an unreachable manager changes nothing, and says so in red.
423	func TestAnUnreachableManagerChangesNeitherTheListingNorTheRefusal(t *testing.T) {
424		m := groupModel(t)
425		m = feed(t, m, RegistryGroupDetectedMsg{
426			RegistryURL: "registry.example.com", Slug: "prod", Err: refusalOf(403, false), At: at(7),
427		})
428		m = feed(t, m, testutil.Key("ctrl+r"))
429		refusal := m.groupRefusals["prod"]
430	
431		m = feed(t, m, RegistryGroupDetectedMsg{
432			RegistryURL: "registry.example.com", Slug: "prod", Err: errUnreachable{}, At: at(8),
433		})
434	
435		if got := m.groupRefusals["prod"]; got != refusal || got.Status != 403 {
436			t.Errorf("groupRefusals[prod] = %+v, want the earlier refusal %+v kept (the refusal is still the last known fact)", got, refusal)
437		}
438		if entry := m.groupCache["prod"]; len(entry.Members) != 2 || !entry.DiscoveredAt.Equal(at(3)) {
439			t.Errorf("groupCache[prod] = %+v, want what was last known", entry)
440		}
441		if m.refreshingGroups["prod"] {
442			t.Error("the discovery is still shown as running after the failure")
443		}
444		if m.footer.Level() != sharedcomponents.LevelError {
445			t.Errorf("footer level = %v, want Error for an unreachable manager (%q)", m.footer.Level(), m.footer.Text())
446		}
447	}
