500	// CA6: an old cache file holds empty entries a refusal may have written. Read
501	// through the UI's load, they come out unknown ("never"), not as "0 members"; an
502	// entry with members is kept.
503	func TestALegacyCacheFileGivesNeverForItsEmptyEntries(t *testing.T) {
504		home := isolateGroupHome(t)
505		legacy := `{
506	  "prod":  {"members": [], "discovered_at": "2026-08-01T10:00:00Z"},
507	  "other": {"members": [{"alias":"a","url":"u","repo_prefix":"a"}], "discovered_at": "2026-08-01T10:00:00Z"}
508	}`
509		if err := os.MkdirAll(filepath.Dir(groupCacheFile(home)), 0o755); err != nil {
510			t.Fatal(err)
511		}
512		if err := os.WriteFile(groupCacheFile(home), []byte(legacy), 0o600); err != nil {
513			t.Fatal(err)
514		}
515	
516		msg, ok := run(t, loadRegistryGroupCache()).(RegistryGroupCacheLoadedMsg)
517		if !ok {
