20	// DEVDESK-510 (NX-07), step 4: what a refused group says, and where. Red phase.
21	//
22	// Formats decided with the UX answer (US English, plain text in cells, Rule 122):
23	//
24	//	Members cell, refused, nothing listed:  "denied · <TimeAgo(refusal.At)>"
25	//	Members cell, refused, N members known: "denied · N known · <TimeAgo(refusal.At)>"
26	//	  (the state comes first, the count last known stays visible, D23; the age is
27	//	  the refusal's, the last attempt. The column has to be wide enough to hold it
28	//	  whole: the tests read the rendered row, not only the cell.)
29	//	Members cell, settled empty:            "0 · <TimeAgo>"  (unchanged)
30	//	Members cell, never probed:             "never"          (unchanged)
31	//	Members cell, listing newer than the refusal: the refusal is stale and the
32	//	  cell is the plain "N · <TimeAgo(listing)>".
33	//
34	// Status line (derived on every render, no timer, no new shortcut):
35	//
36	//	refused:                   Warn  "Members could not be read with this account — declare them by hand with repo_prefix"
37	//	refused, N declared:       Warn  "Members could not be read with this account — N declared by hand are used"
38	//	settled empty (0 members): Info  "No member found — this group is empty"
39	//
40	// The footer is never the only trace: the cell carries the state as a word.
41	
42	const (
43		statusRefusedLine  = "Members could not be read with this account — declare them by hand with repo_prefix"
44		statusDeclaredFmt  = "Members could not be read with this account — %d declared by hand are used"
45		statusEmptyGroup   = "No member found — this group is empty"
46		drillInNoMembers   = "No members to open — declare them by hand with repo_prefix"
47		registryHostInTest = "registry.example.com"
48	)
