52		name    string
53		refusal cache.RegistryGroupRefusal
54	}{
55		{"403 account", cache.RegistryGroupRefusal{At: at(7), Status: 403}},
56		{"401 account", cache.RegistryGroupRefusal{At: at(7), Status: 401}},
57		{"anonymous", cache.RegistryGroupRefusal{At: at(7), Status: 403, Anonymous: true}},
58	}
